### 创建站点配置文件

配置名字`dekviw-blog.conf`可以自己随便改

```bash
cat > /root/data/hexo-webhook/nginx/conf.d/dekviw-blog.conf << 'EOF'
server {
    listen 80;
    server_name localhost;

    # 应用全局限制
    limit_req zone=example_zone burst=100 nodelay;
    limit_conn addr 25;

    # 自定义的404页面
    error_page 404 /404.html;
    location = /404.html {
        root /usr/share/nginx/html;
        internal;
    }

    # 处理 /static 路径
    location /static/ {
        root /usr/share/nginx/html;
        expires 1d;
        add_header Cache-Control "public";

        # 静态资源缓存
        location ~* \.(css|js|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|webp|avif)$ {
            expires 1y;
            add_header Cache-Control "public, immutable";
            access_log off;
        }
    }

    # 处理 /unhxi 路径
    location /unhxi/ {
        root /usr/share/nginx/html;
        autoindex on;
        autoindex_exact_size off;
        autoindex_localtime on;
        expires 1d;

        # 下载文件缓存
        location ~* \.(zip|rar|7z|tar|gz|bz2|pdf|doc|docx|xls|xlsx|ppt|pptx)$ {
            expires 7d;
            add_header Cache-Control "public";
        }
    }

    # 根路径及其他子路径配置
    location / {
        root /usr/share/nginx/html/hexo;
        index index.html;
        try_files $uri $uri/ =404;

        # 静态资源缓存
        location ~* \.(css|js|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|webp|avif)$ {
            expires 1y;
            add_header Cache-Control "public, immutable";
            access_log off;
        }

        # HTML 文件缓存
        location ~* \.html$ {
            expires 1h;
            add_header Cache-Control "public, must-revalidate";
        }
    }

    # 健康检查
    location /health {
        access_log off;
        return 200 "healthy\n";
        add_header Content-Type text/plain;
    }

    # 安全配置
    location ~ /\. {
        deny all;
        access_log off;
        log_not_found off;
    }

    # 隐藏版本信息
    location ~ /\.ht {
        deny all;
    }
}
EOF
```

