### 创建 Webhook 服务

```bash
cat > /root/data/hexo-webhook/scripts/webhook-server.js << 'EOF'
const express = require('express');
const crypto = require('crypto');
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

// 加载配置
const config = require('./config');

const app = express();
const PORT = config.PORT;
const SECRET = config.WEBHOOK_SECRET;
const NGINX_HTML_PATH = config.NGINX_HTML_PATH;

app.use(express.json());

// 验证 webhook 签名
function verifySignature(req, res, next) {
    const signature = req.headers['x-hub-signature-256'];
    if (!signature) {
        return res.status(401).json({ error: 'Missing signature' });
    }

    const bodyString = JSON.stringify(req.body);
    const expectedSignature = 'sha256=' + crypto
        .createHmac('sha256', SECRET)
        .update(bodyString)
        .digest('hex');

    if (signature !== expectedSignature) {
        return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
}



// 部署博客
function deployBlog() {
    return new Promise((resolve, reject) => {
        console.log('开始部署博客...');

        // 切换到博客目录
        process.chdir(NGINX_HTML_PATH);

        // 执行 Git 操作
        const commands = [
            'git fetch origin',
            'git reset --hard origin/main',
            'git clean -fd'
        ];

        let currentCommand = 0;

        function executeNext() {
            if (currentCommand >= commands.length) {
                console.log('部署完成');

                // 重新创建 .gitignore 文件以保护个性化目录
                try {
                    const gitignoreContent = `# 作者个性化目录（可根据需要调整）
cizhi/
upimg/
rmbg/
qrc/
fyh/
bbd/
bzsm/
nav/
wzq/

# 确保 .gitignore 文件本身不被忽略
!.gitignore
`;

                    fs.writeFileSync('.gitignore', gitignoreContent);
                    console.log('.gitignore 文件已重新创建，个性化目录得到保护');
                } catch (error) {
                    console.warn('创建 .gitignore 文件失败:', error.message);
                    // 不阻止部署流程，只记录警告
                }

                resolve();
                return;
            }

            const command = commands[currentCommand];
            console.log(`执行命令: ${command}`);

            exec(command, (error, stdout, stderr) => {
                if (error) {
                    console.error(`命令执行失败: ${command}`, error);
                    reject(error);
                    return;
                }

                if (stdout) console.log(stdout);
                if (stderr) console.log(stderr);

                currentCommand++;
                executeNext();
            });
        }

        executeNext();
    });
}



// Webhook 端点
app.post('/webhook', verifySignature, async (req, res) => {
    try {
        console.log('收到 webhook 请求:', req.body);

        // 部署博客
        await deployBlog();

        // 验证部署是否成功
        if (!fs.existsSync(path.join(NGINX_HTML_PATH, 'index.html'))) {
            throw new Error('部署后未找到 index.html');
        }

        res.json({
            success: true,
            message: '部署成功'
        });

    } catch (error) {
        console.error('Webhook 处理错误:', error);
        res.status(500).json({
            error: '部署失败',
            details: error.message
        });
    }
});

// 健康检查端点
app.get('/health', (req, res) => {
    res.json({
        status: 'healthy',
        timestamp: new Date().toISOString(),
        config: {
            port: PORT,
            nginxPath: NGINX_HTML_PATH
        }
    });
});

// 启动服务器
app.listen(PORT, () => {
    console.log(`Webhook 服务器运行在端口 ${PORT}`);
    console.log(`博客路径: ${NGINX_HTML_PATH}`);
    console.log(`配置加载完成`);
});
EOF
