        }
    }
    // 页面加载时的默认数据
    window.onload = function() {
        buildToolInterface(); // 确保在页面加载后构建工具界面
        const randomIp = getRandomIp();
        const defaultData = `[[["*google*","*youtube.com","*.ggpht.com","i.ytimg.com"],"g.cn","${randomIp}"]]`;
        document.getElementById('in').value = defaultData;

        // 按钮事件绑定
        document.getElementById('fetchButton').addEventListener('click', fetchData);
        document.getElementById('processButton').addEventListener('click', processDataFromInput);
